
 SET TIME ZONE 'UTC';
 CREATE TABLE clients(id bigint PRIMARY KEY);
 CREATE TABLE crm_v2_clients(id bigint PRIMARY KEY,name text,status text);
 CREATE TABLE crm_v2_client_relationships(client_id bigint,relationship_type text,status text);
 CREATE TABLE staff_admin_accounts(id bigint PRIMARY KEY,staff_id bigint,display_name text,permissions jsonb,business_role text,service_scope text,active bool);
 CREATE TABLE service_categories(id bigint PRIMARY KEY,name text,status text,display_order int);
 CREATE TABLE staff(id bigint PRIMARY KEY,display_name text,status text,resource_type text,client_bookable bool,business_role text);
 CREATE TABLE services(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id bigint,name text,duration_minutes int,processing_time_minutes int DEFAULT 0,extra_time_minutes int DEFAULT 0,variable_price bool DEFAULT false,price numeric(12,2),display_price text,customer_description text,booking_note text,display_order int DEFAULT 0,is_default bool DEFAULT false,status text DEFAULT 'active',external_source text,external_id text,updated_at timestamptz DEFAULT now(),UNIQUE(external_source,external_id));
 CREATE TABLE staff_services(staff_id bigint,service_id bigint,PRIMARY KEY(staff_id,service_id));
 CREATE TABLE service_visibility_policies(service_id bigint,owner_staff_id bigint);
 CREATE TABLE appointments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,client_id bigint,crm_v2_client_id bigint,starts_at timestamptz,ends_at timestamptz,status text DEFAULT 'scheduled',total_price numeric,notes text,updated_at timestamptz DEFAULT now());
 CREATE TABLE appointment_services(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,appointment_id bigint,service_id bigint,price_snapshot numeric);
 CREATE TABLE crm_audit_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_admin_id bigint,action text,entity_type text,entity_id text,metadata jsonb);
